#include "local_embedding.h"
#include <iostream>
int main(int argc,char **argv){ if(argc<2)return 2; llama_log_set([](ggml_log_level,const char*,void*){},nullptr);ggml_backend_load_all();llama_backend_init();try{LocalEmbedding engine(argv[1]);auto q=engine.embed("task: search result | query: How do I reset my password?");auto a=engine.embed("title: none | text: To recover account access, use the forgot password link and confirm the email.");auto b=engine.embed("title: none | text: Banana bread is baked with ripe fruit, flour and butter.");double same=0,other=0,norm=0;for(int i=0;i<768;i++){same+=q[i]*a[i];other+=q[i]*b[i];norm+=q[i]*q[i];}std::cout<<"{\"dimensions\":768,\"norm\":"<<norm<<",\"relevantCosine\":"<<same<<",\"unrelatedCosine\":"<<other<<"}"<<std::endl;return same>other&&fabs(norm-1)<0.001?0:1;}catch(const std::exception&x){std::cerr<<x.what()<<std::endl;return 3;}}
